const {test}=require('node:test'),assert=require('node:assert/strict');
const A=require('./aliyun-retrieval-model'),M=require('./model');
const state=()=>({sequence:600,issues:[{id:'I',status:'调查中',device:'business-device',version:'v',build:'b',requests:[]}],collectionRequests:[]});
const form=()=>({...A.draft(),targetValue:'synthetic-device-for-qa'});
function finish(r){for(let n=0;n<5;n++)A.advance(r,M);}
test('工单普通设备字段不冒充阿里云 deviceId，明确保存的参数可带入',()=>{const i=state().issues[0];assert.equal(A.draft(i).targetValue,'');i.aliyunPush={app:A.app.packageName,targetType:'account',targetValue:'qa-user'};assert.equal(A.draft(i).targetType,'account');assert.equal(A.draft(i).targetValue,'qa-user');assert.equal(A.draft(i).bindingConfirmed,false);});
test('设备账号别名保持原值，标签拒绝，账号别名必须人工确认绑定',()=>{for(const type of ['account','alias']){assert.throws(()=>A.validate({...form(),targetType:type}),/绑定/);A.validate({...form(),targetType:type,bindingConfirmed:true});}assert.throws(()=>A.validate({...form(),targetType:'tag'}),/标签/);assert.throws(()=>A.validate({...form(),targetValue:''}),/目标值/);});
test('账号与别名不伪造设备或构建身份，也不生成未知推送命令',()=>{const s=state(),r=A.create(s,{...form(),targetType:'account',bindingConfirmed:true,issueId:'I'},M);assert.equal(r.device,'待客户端上报');assert.equal(r.version,null);assert.equal(r.build,null);assert.equal(r.product.push,undefined);assert.equal(r.product.aliyun.notificationExtras,null);assert.equal(s.issues[0].device,'business-device');assert.equal(s.issues[0].aliyunPush.targetValue,'synthetic-device-for-qa');});
test('回捞成功发生在平台接收之后、解析之前，解析失败不抹去回捞成功',()=>{const r=A.create(state(),{...form(),scenario:'parsefail'},M);for(let n=0;n<3;n++)A.advance(r,M);assert.equal(r.product.aliyun.platformReceived,false);assert.equal(r.files.length,0);A.advance(r,M);assert.equal(r.product.aliyun.retrievalStatus,'回捞成功');assert.equal(r.task,null);assert.equal(r.status,'解析中');A.advance(r,M);assert.equal(r.status,'解析失败');assert.equal(r.product.aliyun.retrievalStatus,'回捞成功');assert.equal(r.files[0].status,'解析失败');});
test('推送失败、接收超时、无日志、上传失败均不伪造平台接收',()=>{for(const scenario of ['pushfail','timeout','empty','uploadfail']){const r=A.create(state(),{...form(),scenario},M);finish(r);assert.equal(r.product.aliyun.platformReceived,false);assert.equal(r.task,null);assert.notEqual(r.product.aliyun.retrievalStatus,'回捞成功');}});
test('同目标进行中请求防重复，不把不同账号折叠成同设备',()=>{const s=state();A.create(s,{...form(),targetType:'account',bindingConfirmed:true},M);assert.throws(()=>A.create(s,{...form(),targetType:'account',bindingConfirmed:true},M),/进行中/);A.create(s,{...form(),targetType:'account',targetValue:'another-user',bindingConfirmed:true},M);assert.equal(s.collectionRequests.length,2);});
test('故障时段可不填，但填写时必须完整有效；不猜测端侧粒度',()=>{A.validate(form(),true);assert.throws(()=>A.validate({...form(),begin:'bad',end:'bad'},true),/有效/);const r=A.create(state(),form(),M);assert.equal(r.product.profile,'unconfirmed');assert.equal(r.product.scope.expanded,false);});
test('终态重复推进不增加通知或回执',()=>{const r=A.create(state(),form(),M);finish(r);const before=JSON.stringify(r);A.advance(r,M);assert.equal(JSON.stringify(r),before);assert.equal(r.events.filter(e=>e.text.startsWith('生成本地站内通知')).length,1);});
